CREATE TABLE Clientes (
    cliente_id INT PRIMARY KEY,
    segmento VARCHAR(100),
    porte VARCHAR(50),
    plano VARCHAR(100),
    valor_mensal DECIMAL(10,2),
    sla_contratado_h INT,
    inicio_contrato DATE
);


CREATE TABLE Atendimento_Mensal (
    cliente_id INT,
    mes_ref DATE,
    chamados_abertos INT,
    chamados_criticos INT,
    chamados_reabertos INT,
    chamados_dentro_sla INT,
    pct_sla_cumprido DECIMAL(5,2),
    tempo_medio_resolucao_h DECIMAL(10,2),
    reclamacoes_formais INT,
    uso_plataforma_pct DECIMAL(5,2),
    dias_atraso_pagamento INT,
    reunioes_previstas INT,
    reunioes_realizadas INT,

    PRIMARY KEY (cliente_id, mes_ref),

    FOREIGN KEY (cliente_id)
        REFERENCES Clientes(cliente_id)
);


CREATE TABLE Pesquisas_NPS (
    cliente_id INT,
    mes_ref DATE,
    respondeu BIT,
    nota_nps INT,
    classificacao_nps VARCHAR(30),

    PRIMARY KEY (cliente_id, mes_ref),

    FOREIGN KEY (cliente_id)
        REFERENCES Clientes(cliente_id)
);


CREATE TABLE Situacao_Clientes (
    cliente_id INT PRIMARY KEY,
    situacao VARCHAR(30),
    mes_cancelamento DATE,

    FOREIGN KEY (cliente_id)
        REFERENCES Clientes(cliente_id)
);

DROP TABLE IF EXISTS Situacao_Clientes;
DROP TABLE IF EXISTS Pesquisas_NPS;
DROP TABLE IF EXISTS Atendimento_Mensal;
DROP TABLE IF EXISTS Clientes;


